<script>import AppShell from '#lib/components/AppShell.svelte';import {agents} from '#lib/data/projects.js';const departments=['Research','Development','Quality assurance','Coordination'];</script><AppShell><div class="content-wrap"><div class="breadcrumbs">Workspace <span>/</span> Agents</div><header class="page-heading"><div><h1>Agents</h1><p>Agents across all projects</p></div></header><div class="agents-area">{#each departments as department}<section class="agent-group"><header><h2>{department}</h2><span class="count">{agents.filter(agent=>agent.department===department).length}</span></header><div class="agent-directory">{#each agents.filter(agent=>agent.department===department) as agent}<div class="directory-row"><div><strong>{agent.name}</strong><small>{agent.id} · {agent.project}</small></div><span class="agent-status"><i class:online={agent.status==='Online'} class:working={agent.status==='Working'}></i>{agent.status}</span></div>{/each}</div></section>{/each}</div></div></AppShell>